            if side!='B' and r1<h-1: ring+=[(r1+1,j) for j in range(c0,c1+1)]
            if side!='L' and c0>0: ring+= [(i,c0-1) for i in range(r0,r1+1)]
            if side!='R' and c1<w-1: ring+=[(i,c1+1) for i in range(r0,r1+1)]
            ring_ok=all(grid[a][b] in wallset for a,b in ring)
            solid=all((a,b) in cs or grid[a][b] in wallset for a in range(r0,r1+1) for b in range(c0,c1+1))
